<div class="notice">Manual payment ledger. Record payments received outside this website. This form does not charge cards or transfer money. Use an existing reference to update its payment status.</div><div class="management-grid"><section class="panel table-wrap"><h2>Payment records</h2><table><thead><tr><th>Reference / advertisement</th><th>LKR</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach ($items as $row): ?><tr><td><?= e($row['reference']) ?><small>#<?= (int)$row['classified_id'] ?> · <?= e($row['title']) ?></small></td><td><?= number_format($row['amount'],2) ?></td><td><span class="status"><?= e($row['status']) ?></span></td><td><?= e($row['created_at']) ?></td></tr><?php endforeach ?></tbody></table></section><form method="post" class="panel form-stack"><?= csrf() ?><h2>Record a payment</h2><label>Advertisement<select name="classified_id" required><option value="">Choose advertisement</option><?php foreach ($classifiedChoices as $item): ?><option value="<?= (int)$item['id'] ?>">#<?= (int)$item['id'] ?> <?= e($item['title']) ?></option><?php endforeach ?></select></label><?php $field('amount','Amount (LKR)','number','','min="0.01" max="9999999999.99" step="0.01" required'); $field('reference','External payment reference','text','','required maxlength="150"'); ?><label>Status<select name="status"><option value="pending">Pending confirmation</option><option value="paid">Payment confirmed</option><option value="refunded">Refunded externally</option></select></label><button class="button">Save record</button><small class="muted">Confirmed payment makes the advertisement eligible for premium placement. Enable it in Classified reviews.</small></form></div>
